# Generated by rarpar-bench fleet for win-dgpu (windows-x86_64-zen4). Do not edit on the host.
$ErrorActionPreference = 'Continue'
$ProgressPreference = 'SilentlyContinue'
$RunId = 'fleet-testrun'
$Base = 'C:\bench\fleet-stage\fleet-testrun'
$Bin = 'C:\bench\fleet-stage\fleet-testrun\bin'
$R = 'C:\bench\fleet-stage\fleet-testrun\results'
$W = 'C:\bench\work\fleet-testrun'
$Machine = 'windows-x86_64-zen4'
$Corpus = 'C:\bench\corpus'
$Bench = Join-Path $Bin 'rarpar-bench.exe'
$Candidate = Join-Path $Bin 'rarpar.exe'
$OracleRar = 'C:\bench\oracles\UnRAR.exe'
$OraclePar2 = ''
$OraclePar3 = 'C:\bench\fleet-stage\fleet-testrun\oracles\par3.exe'
$Status = 'ok'
$Failures = @()
$Started = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
$StartTicks = [DateTime]::UtcNow
New-Item -ItemType Directory -Force -Path $R, $W | Out-Null
$env:RARPAR_BENCH_WORKSPACE_ROOT = $Base
function Log($m) { Write-Output ("[{0}] {1}" -f (Get-Date).ToUniversalTime().ToString('HH:mm:ss'), $m) }
function Fail($m) { $script:Status = 'failed'; $script:Failures += $m; Log "FAILURE: $m" }
function Gate($what) {
  $names = @('rarpar-bench','rarpar','par2','unrar','decode_timing','searchend_timing','crc_probe')
  $waited = 0
  while ($true) {
    $busy = @()
    foreach ($n in $names) { if (Get-Process -Name $n -ErrorAction SilentlyContinue) { $busy += $n } }
    if ($busy.Count -eq 0) { Log "GATE $what clear (waited ${waited}s)"; return }
    if ($waited -ge 900) { Log "GATE $what proceeding after ${waited}s"; return }
    Log "GATE $what busy: $($busy -join ',')"
    Start-Sleep -Seconds 30; $waited += 30
  }
}
Get-ComputerInfo | Out-File -FilePath (Join-Path $R 'environment.txt') -Encoding utf8
Get-ChildItem $Bin | Out-File -FilePath (Join-Path $R 'binaries.txt') -Encoding utf8
Get-FileHash -Algorithm SHA256 (Get-ChildItem $Bin -File).FullName | Out-File -Append -FilePath (Join-Path $R 'binaries.txt') -Encoding utf8
$probe = Join-Path $Bin 'crc_probe.exe'
if (Test-Path $probe) { Gate 'crc-probe'; & $probe *> (Join-Path $R 'crc_probe.txt') } else { Fail 'crc-probe-binary-missing' }
& $Bench corpus verify --root $Corpus *> (Join-Path $R 'corpus-verify.txt')
$plan = Join-Path $W 'plan-rar.json'
& $Bench plan create --corpus $Corpus --out $plan --seed 'rarpar-benchmark-plan-v1' --lane 'cpu' --family 'rar' --par2-placement 'canonical' --warmups 1 --repeats 7 *> (Join-Path $R 'plan-rar.log')
Copy-Item $plan (Join-Path $R 'plan-rar.json') -ErrorAction SilentlyContinue
Gate 'rar'
$out = Join-Path $W 'run-rar'
Remove-Item -Recurse -Force $out -ErrorAction SilentlyContinue
$benchArgs = @('run','--corpus',$Corpus,'--plan',$plan,'--candidate',$Candidate,'--candidate-label','rarpar','--reference-label','reference','--out',$out,'--machine',$Machine)
if ($OracleRar) { $benchArgs += @('--reference-rar', $OracleRar) }
if ($OraclePar2) { $benchArgs += @('--reference-par2', $OraclePar2) }
& $Bench @benchArgs *> (Join-Path $R 'run-rar.log')
if ($LASTEXITCODE -ne 0) { Fail 'run-rar' }
Copy-Item (Join-Path $out 'raw.json') (Join-Path $R 'raw-rar.json') -ErrorAction SilentlyContinue
& $Bench report --input (Join-Path $out 'raw.json') --out (Join-Path $R 'report-rar.json') *> (Join-Path $R 'report-rar.log')
Remove-Item -Recurse -Force $out -ErrorAction SilentlyContinue
$p3Work = 'C:\p3'
if (Test-Path $OraclePar3) {
  Gate 'macro-par3'
  $p3Args = @('par3','run','--reference',$OraclePar3,'--candidate',$Candidate,'--work',$p3Work,'--out',(Join-Path $R 'par3'),'--machine',$Machine,'--profile','full','--workers','1,8','--warmups','1','--repeats','5','--timeout','20m')
  & $Bench @p3Args *> (Join-Path $R 'par3-run.log')
  if ($LASTEXITCODE -ne 0) { Fail 'macro-par3' }
} else { Fail 'par3-reference-missing' }
Remove-Item -Recurse -Force $p3Work -ErrorAction SilentlyContinue
'capabilities.perf = none on Windows hosts; phase timings only' | Out-File -FilePath (Join-Path $R 'perf-NO-COLLECTOR.txt') -Encoding utf8
$Finished = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
$Elapsed = [int]([DateTime]::UtcNow - $StartTicks).TotalSeconds
$files = Get-ChildItem -Recurse -File $R | Where-Object { $_.Name -ne 'MANIFEST.json' } | ForEach-Object {
  [ordered]@{ path = $_.FullName.Substring($R.Length + 1).Replace('\','/'); bytes = $_.Length; sha256 = (Get-FileHash -Algorithm SHA256 $_.FullName).Hash.ToLower() } }
$manifest = [ordered]@{ schema_version = 1; run_id = $RunId; machine = 'win-dgpu'; platform_label = $Machine; started_utc = $Started; finished_utc = $Finished; elapsed_seconds = $Elapsed; status = $Status; failures = ($Failures -join ' '); files = @($files) }
$manifest | ConvertTo-Json -Depth 5 | Out-File -FilePath (Join-Path $R 'MANIFEST.json') -Encoding utf8
Add-Type -AssemblyName System.IO.Compression.FileSystem
Remove-Item -LiteralPath 'C:\bench\fleet-stage\fleet-testrun\results.zip' -Force -ErrorAction SilentlyContinue
[IO.Compression.ZipFile]::CreateFromDirectory($R, 'C:\bench\fleet-stage\fleet-testrun\results.zip')
$tarHash = (Get-FileHash -Algorithm SHA256 'C:\bench\fleet-stage\fleet-testrun\results.zip').Hash.ToLower()
$tarBytes = (Get-Item 'C:\bench\fleet-stage\fleet-testrun\results.zip').Length
@("status=$Status", "run_id=$RunId", "machine=win-dgpu", "started_utc=$Started", "finished_utc=$Finished", "elapsed_seconds=$Elapsed", "tarball=C:\\bench\\fleet-stage\\fleet-testrun\\results.zip", "tarball_sha256=$tarHash", "tarball_bytes=$tarBytes", "files=$($files.Count)", "failures=$($Failures -join ' ')") | Out-File -FilePath 'C:\bench\fleet-stage\fleet-testrun\DONE.tmp' -Encoding ascii
Move-Item -Force 'C:\bench\fleet-stage\fleet-testrun\DONE.tmp' 'C:\bench\fleet-stage\fleet-testrun\DONE'
Log "RUN COMPLETE status=$Status elapsed=${Elapsed}s"
